import json, pathlib, collections, hashlib
manifest=json.load(open('/tmp/aug-manifest.json'))
p=manifest['candidates']; tasks=manifest['tasks']; out=pathlib.Path('/tmp/aug-files')

def fn(f):
    return out/(hashlib.sha1(f.encode()).hexdigest()+'.json')

split_map={
    'DanFeverRetrieval':['train'],
    'DanishPoliticalCommentsClassification':['train'],
    'TwitterHjerneRetrieval':['train'],
    'SwednClusteringP2P':['summaries','articles'],
    'SwednClusteringS2S':['headlines'],
    'MassiveIntentClassification':['validation','test'],
    'MassiveScenarioClassification':['validation','test'],
}

def wanted(t): return split_map.get(t,['test'])
all_data=collections.defaultdict(lambda:collections.defaultdict(list))
for m,fs in p.items():
    for f in fs:
        if not any(f.endswith('/'+t+'.json') for t in tasks): continue
        t=f.rsplit('/',1)[-1][:-5]; rev=f.split('/')[2]; j=json.load(open(fn(f)))
        vals=[]
        if 'scores' in j:
            for split in wanted(t):
                for x in j['scores'].get(split,[]):
                    if isinstance(x,dict) and x.get('main_score') is not None:
                        vals.append((split,x.get('hf_subset','default'),float(x['main_score'])))
        else:
            for split in wanted(t):
                x=j.get(split)
                if isinstance(x,dict) and 'main_score' in x:
                    vals.append((split,x.get('hf_subset','default'),float(x['main_score'])))
                elif isinstance(x,dict):
                    for k,v in x.items():
                        if isinstance(v,dict) and 'main_score' in v:
                            vals.append((split,v.get('hf_subset',k),float(v['main_score'])))
        for split,subset,score in vals:
            all_data[m][t].append((rev,split,subset,score,f))

for m in p:
    print('\nMODEL',m)
    byrev=collections.defaultdict(dict)
    for t in tasks:
        # for task with multiple configured splits, average them
        x=collections.defaultdict(list)
        for rev,sp,sub,sc,f in all_data[m][t]: x[rev].append(sc)
        for rev,vals in x.items(): byrev[rev][t]=sum(vals)/len(vals)
    for rev,ds in byrev.items():
        if len(ds)>=20:
            print(' REV',rev,'n',len(ds),'mean',sum(ds.values())/len(ds),'missing',set(tasks)-set(ds))
    # max duplicate revisions per (task, split, subset), then average splits/subsets per task
    ds={}
    for t in tasks:
        bykey=collections.defaultdict(list)
        for rev,sp,sub,sc,f in all_data[m][t]: bykey[(sp,sub)].append(sc)
        taskvals=[max(v) for v in bykey.values()]
        if taskvals: ds[t]=sum(taskvals)/len(taskvals)
    print(' UNION max n',len(ds),'mean',sum(ds.values())/len(ds) if len(ds)==len(tasks) else None,'missing',set(tasks)-set(ds))
    print(' scores', ' '.join(f'{t}={ds.get(t,0):.4f}' for t in tasks))

